// 42-tap direct-form FIR, 8-bit samples, unpipelined MAC cone (the long
// register-to-register path -> lower Fmax; pipeline it to go faster).
module firr42_v5 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [7:0]  xs [0:41];
    integer     i;
    reg  [23:0] acc;
    always @(*) acc = 8'd5 * xs[0] + 8'd12 * xs[1] + 8'd19 * xs[2] + 8'd26 * xs[3] + 8'd33 * xs[4] + 8'd40 * xs[5] + 8'd47 * xs[6] + 8'd54 * xs[7] + 8'd61 * xs[8] + 8'd68 * xs[9] + 8'd75 * xs[10] + 8'd82 * xs[11] + 8'd89 * xs[12] + 8'd96 * xs[13] + 8'd103 * xs[14] + 8'd110 * xs[15] + 8'd117 * xs[16] + 8'd124 * xs[17] + 8'd131 * xs[18] + 8'd138 * xs[19] + 8'd145 * xs[20] + 8'd152 * xs[21] + 8'd159 * xs[22] + 8'd166 * xs[23] + 8'd173 * xs[24] + 8'd180 * xs[25] + 8'd187 * xs[26] + 8'd194 * xs[27] + 8'd201 * xs[28] + 8'd208 * xs[29] + 8'd215 * xs[30] + 8'd222 * xs[31] + 8'd229 * xs[32] + 8'd236 * xs[33] + 8'd243 * xs[34] + 8'd250 * xs[35] + 8'd257 * xs[36] + 8'd264 * xs[37] + 8'd271 * xs[38] + 8'd278 * xs[39] + 8'd285 * xs[40] + 8'd292 * xs[41];
    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 42; i = i + 1) xs[i] <= 8'd0;
            y <= 16'd0;
        end else begin
            xs[0] <= x;
            for (i = 1; i < 42; i = i + 1) xs[i] <= xs[i-1];
            y <= acc[15:0];
        end
    end
endmodule
